#include <vector>
#include <algorithm>

using namespace std;
//Driver Code Ends


int maxProfit(vector<int> &arr, int k) {
    int n = arr.size();

    int noStock = 0, inHand = 0;

    for (int i = n - 1; i >= 0; i--) {

        // Choose to buy or skip
        int newNoStock = max(noStock, inHand - arr[i]);

        // Choose to sell or skip
        int newInHand = max(inHand, arr[i] - k + noStock);

        // Update states
        noStock = newNoStock;
        inHand = newInHand;
    }

    return noStock;
}


